import RiveRuntime
import SwiftUI

/// The blinking Axo axolotl: the `Face` artboard of `axo.riv` (generated by
/// `packages/axo-mascot`), whose `Mascot` state machine decides when to blink.
/// With Reduce Motion on it holds still.
struct AxoMascotView: View {
  /// The `Face` artboard is 1064 x 564.
  static let aspectRatio = 1064.0 / 564.0

  @Environment(\.accessibilityReduceMotion) private var reduceMotion
  @State private var rive: Rive?

  var body: some View {
    ZStack {
      if let rive {
        RiveUIViewRepresentable(rive: rive).paused(reduceMotion)
      }
    }
    .aspectRatio(Self.aspectRatio, contentMode: .fit)
    .accessibilityElement()
    .accessibilityLabel("Axo")
    .accessibilityAddTraits(.isImage)
    .task {
      do {
        rive = try await MascotFile.shared.makeRive()
      } catch {
        // The mascot is decoration; without it the layout keeps its space.
      }
    }
  }
}

/// One Rive worker and file for every mascot on screen; each view gets its own artboard.
@MainActor
final class MascotFile {
  static let shared = MascotFile()

  private var loading: Task<File, any Error>?

  func makeRive() async throws -> Rive {
    let file = try await load()
    let artboard = try await file.createArtboard("Face")
    let stateMachine = try await artboard.createStateMachine("Mascot")
    return try await Rive(file: file, artboard: artboard, stateMachine: stateMachine)
  }

  private func load() async throws -> File {
    if let loading { return try await loading.value }
    let task = Task { @MainActor () throws -> File in
      guard let url = Bundle.main.url(forResource: "axo", withExtension: "riv") else {
        throw CocoaError(.fileNoSuchFile)
      }
      let worker = try await Worker()
      return try await File(source: .data(try Data(contentsOf: url)), worker: worker)
    }
    loading = task
    return try await task.value
  }
}
